	public void unAssignPipeline( UnAssignPipelineFromDataTaskCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignPipeline(command.getDataTaskId());
	}
	

